    qo_state.mode = QO_FAULT;
    qo_output.mode = QO_FAULT;
    qo_output.good = qo_state.good;
    qo_output.usable = 0;
    qo_output.total_weight = 0.0;
    qo_output.mean_alignment = 0.0;
    qo_output.body_separation_sine = 0.0;
    qo_output.reference_separation_sine = 0.0;
    qo_output.weighted_body = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

// 3. Validate Configuration
if (!isfinite(qo_config.minimum_weight) || qo_config.minimum_weight <= 0.0 ||
    !isfinite(qo_config.minimum_separation_sine) || qo_config.minimum_separation_sine <= 0.0 ||
    qo_config.minimum_separation_sine > 1.0 ||
    qo_config.required_good < 1 || qo_config.required_good > 10 ||
    qo_config.max_consecutive_bad > 10) {
    qo_state.mode = QO_FAULT;
    qo_output.mode = QO_FAULT;
    qo_output.good = qo_state.good;
    qo_output.usable = 0;
    qo_output.total_weight = 0.0;
    qo_output.mean_alignment = 0.0;
    qo_output.body_separation_sine = 0.0;
    qo_output.reference_separation_sine = 0.0;
    qo_output.weighted_body = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

// 4. Process Observations
double total_weight = 0.0;
adcs_vec3_t weighted_body = {0.0, 0.0, 0.0};
double alignment_numerator = 0.0;
adcs_vec3_t norm_body[3];
adcs_vec3_t norm_ref[3];
int data_valid = 1;

for (size_t i = 0; i < qo_input.count; ++i) {
    if (!isfinite(qo_input.weights[i]) || qo_input.weights[i] <= 0.0) {
        data_valid = 0;
        break;
    }
    if (!adcs_is_finite_vec3(&qo_input.body[i]) || !adcs_is_finite_vec3(&qo_input.reference[i])) {
        data_valid = 0;
        break;
