    adcs_status_t st_r = adcs_vec3_normalize(&qo_input.reference[i], ADCS_EPS_NORM, &norm_ref[i]);

    if (st_b != ADCS_OK || st_r != ADCS_OK) {
        data_valid = 0;
        break;
    }

    total_weight += qo_input.weights[i];

    adcs_vec3_t term = adcs_vec3_scale(&norm_body[i], qo_input.weights[i]);
    weighted_body = adcs_vec3_add(&weighted_body, &term);

    alignment_numerator += qo_input.weights[i] * adcs_vec3_dot(&norm_body[i], &norm_ref[i]);
}

if (!data_valid) {
    qo_state.mode = QO_FAULT;
    qo_output.mode = QO_FAULT;
    qo_output.good = qo_state.good;
    qo_output.usable = 0;
    qo_output.total_weight = 0.0;
    qo_output.mean_alignment = 0.0;
    qo_output.body_separation_sine = 0.0;
    qo_output.reference_separation_sine = 0.0;
    qo_output.weighted_body = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

double mean_alignment = (total_weight > 0.0) ? (alignment_numerator / total_weight) : 0.0;

// 5. Compute Separation Sines
double body_sep_sine = 0.0;
double ref_sep_sine = 0.0;

if (qo_input.count >= 2) {
    adcs_vec3_t cross_b = adcs_vec3_cross(&norm_body[0], &norm_body[1]);
    body_sep_sine = adcs_vec3_norm(&cross_b);

    adcs_vec3_t cross_r = adcs_vec3_cross(&norm_ref[0], &norm_ref[1]);
    ref_sep_sine = adcs_vec3_norm(&cross_r);
}

// 6. Determine Usability
unint32 usable = 0;
if (total_weight >= qo_config.minimum_weight &&
    body_sep_sine >= qo_config.minimum_separation_sine &&
    ref_sep_sine >= qo_config.minimum_separation_sine) {
    usable = qo_input.count;
}

// 7. State Machine Transition
if (usable > 0) {
    qo_state.bad_streak = 0;
    qo_state.good++;

    if (qo_state.good >= qo_config.required_good) {
        qo_state.mode = QO_SOLVE;
    } else {
        qo_state.mode = QO_WAIT;
    }
} else {
    // Unusable but valid format
    qo_state.bad_streak++;

    if (qo_state.bad_streak > qo_config.max_consecutive_bad) {
        qo_state.good = 0;
        qo_state.bad_streak = 0;
        qo_state.mode = QO_WAIT;
    } else {
        qo_state.mode = QO_HOLD;
    }
}

// 8. Populate Output
qo_output.mode = qo_state.mode;
qo_output.good = qo_state.good;
qo_output.usable = usable;
qo_output.total_weight = total_weight;
qo_output.mean_alignment = mean_alignment;
qo_output.body_separation_sine = body_sep_sine;
qo_output.reference_separation_sine = ref_sep_sine;
qo_output.weighted_body = weighted_body;

